const EgtMoneySummary=(function(){const cents=x=>Math.round((x||0)*100)/100;function money(n,opts){const v=cents(n);if(!v&&(opts&&opts.dashZero))return"—";return`${v<0?"−":"+"}$${Math.abs(v).toFixed(2).replace(/\.00$/,"")}`}const tone=n=>cents(n)>0?"up":cents(n)<0?"down":"flat";function workLines(model,roundId,res,nameOf){const r=res||{};const out=[];const list=totals=>Object.keys(totals||{}).sort((a,b)=>(totals[b]||0)-(totals[a]||0)).map(pid=>`${nameOf(pid)} ${totals[pid]}`).join(" · ");const topOf=totals=>{const ids=Object.keys(totals||{});if(!ids.length)return"";const best=Math.max(...ids.map(id=>totals[id]||0));return ids.filter(id=>(totals[id]||0)===best).map(nameOf).join(" & ")};const seg=(m,s)=>!s||s.winner==="halve"?"halved":`${nameOf(m.sides[s.winner==="A"?0:1][0])} by ${Math.abs(s.up)}`;const matchCash=m=>[[m.front,1],[m.back,1],[m.overall,2]].reduce((a,pair)=>{const s=pair[0];return a+(!s||s.winner==="halve"?0:pair[1]*(m.stakes||0)*(s.winner==="A"?1:-1))},0);const matchLine=m=>{const a=m.sides[0][0],b=m.sides[1][0];const net=matchCash(m);const paid=!net?"no money":`${nameOf(net>0?a:b)} +$${Math.abs(net)}`;return`${nameOf(a)} v ${nameOf(b)} — front ${seg(m,m.front)} · back ${seg(m,m.back)} · overall ${seg(m,m.overall)} → ${paid}`};const teamName=nm=>{const round=model.rounds.find(x=>x.id===roundId);const t=(round&&round.teams||[]).find(x=>x.name===nm);return t?t.players.map(nameOf).join(" + "):nm};if(r.bbb&&r.bbb.ranked&&r.bbb.ranked.length){out.push(`Bingo Bango Bongo — ${list(r.bbb.totals)} → ${topOf(r.bbb.totals)} takes the stake from each player`)}if(r.nines&&r.nines.ranked&&r.nines.ranked.length){out.push(`The Nines — ${list(r.nines.totals)} → ${topOf(r.nines.totals)} takes the stake from each player`)}if(r.fourBall){const ov=r.fourBall.segments.overall;out.push(ov.winnerTeam==="halve"?"Four-ball — all square, no money":`Four-ball — ${teamName(ov.winnerTeam)} by ${Math.abs(ov.up)} → each winner collects from each opponent`)}if(r.wolf&&r.wolf.units){const u=r.wolf.units;const units=Object.keys(u).sort((a,b)=>(u[b]||0)-(u[a]||0)).map(pid=>`${nameOf(pid)} ${u[pid]<0?"−":"+"}${Math.abs(u[pid])}`).join(" · ");out.push(`Wolf units — ${units} → ${topOf(u)} takes the stake from each player`)}if(r.teamStableford){const ts=r.teamStableford;out.push(`Stableford points — ${list(ts.playerPoints)}`);const names=Object.keys(ts.teamTotals);out.push(`Teams — ${names.map(n=>`${teamName(n)} ${ts.teamTotals[n]}`).join(" v ")} → ${ts.overallWinner==="halve"?"tied, no money":`${teamName(ts.overallWinner)} take it`}`)}if(r.stableford&&r.stableford.totals){out.push(`Stableford — ${list(r.stableford.totals)} → ${topOf(r.stableford.totals)} takes the stake from each player`)}const matches=r.overlayMatchPlay&&r.overlayMatchPlay.matches||[];const oneVOne=matches.filter(m=>m.sides[0].length===1&&m.sides[1].length===1);if(oneVOne.length>2)out.push("Match play, front · back · overall at each match’s stake:");oneVOne.forEach(m=>out.push((oneVOne.length>2?"   ":"")+matchLine(m)));return out}function settleUp(money2){const settlements=money2&&money2.settlements||[];const extras=money2&&money2.extras;const flows=[];(extras&&extras.items||[]).forEach(item=>{const t=item.total||{};Object.entries(item.prepaid||{}).forEach(([payer,amt])=>{if(!(t[payer]<0)||!amt)return;const winners=Object.keys(t).filter(id=>t[id]>0);const pot=winners.reduce((a,id)=>a+t[id],0);if(!pot)return;winners.forEach(w=>flows.push({from:payer,to:w,amount:amt*t[w]/pot}))})});const unapplied={};const rows=settlements.map(s=>{const raw=cents(flows.filter(f=>f.from===s.from&&f.to===s.to).reduce((a,f)=>a+f.amount,0));const amount=cents(s.amount);const credit=Math.min(raw,amount);if(raw>credit)unapplied[s.from]=cents((unapplied[s.from]||0)+(raw-credit));return{from:s.from,to:s.to,amount,credit:cents(credit),due:cents(amount-credit)}});rows.unapplied=unapplied;return rows}function build(model,live){const money2=live&&live.money||{};const nameOf=pid=>((model.playersById||{})[pid]||{}).name||pid;const ids=(model.players||[]).map(p=>p.id);const roundIds=(model.rounds||[]).map(r=>r.id);const finalized=Object.keys(money2.rounds||{}).filter(k=>roundIds.includes(k));const totalOf=pid=>cents((money2.total||{})[pid]);const golfOf=pid=>cents((money2.golfOnly||money2.total||{})[pid]);const extrasOf=pid=>cents(((money2.extras||{}).total||{})[pid]);const standings=ids.slice().sort((a,b)=>totalOf(b)-totalOf(a)).map(pid=>({id:pid,name:nameOf(pid),total:totalOf(pid),golf:golfOf(pid),extras:extrasOf(pid),tone:tone(totalOf(pid)),verdict:totalOf(pid)>0?"collects":totalOf(pid)<0?"pays out":"square"}));const rounds=(model.rounds||[]).slice().sort((a,b)=>(a.seq||0)-(b.seq||0)).filter(r=>(money2.rounds||{})[r.id]).map(r=>{const course=(model.courses||{})[r.courseId]||{};const by={};ids.forEach(pid=>{by[pid]=cents(money2.rounds[r.id].total[pid])});return{id:r.id,seq:r.seq,date:r.date,course:course.name||r.courseId,players:r.players||ids,by,work:workLines(model,r.id,(live.resultsByRound||{})[r.id],nameOf)}});const extras=((money2.extras||{}).items||[]).map(it=>{const by={};ids.forEach(pid=>{by[pid]=cents((it.total||{})[pid])});return{id:it.id,label:it.label,note:it.note||null,by}});const golfOnly={};ids.forEach(pid=>{golfOnly[pid]=golfOf(pid)});const total={};ids.forEach(pid=>{total[pid]=totalOf(pid)});const settle=settleUp(money2);const prepaid=(money2.extras||{}).prepaid||{};const prepaidNote=Object.keys(prepaid).map(pid=>{const owed=settle.filter(s=>s.from===pid).reduce((a,s)=>a+s.amount,0);const due=settle.filter(s=>s.from===pid).reduce((a,s)=>a+s.due,0);return{id:pid,name:nameOf(pid),amount:cents(prepaid[pid]),owed:cents(owed),due:cents(due),refund:cents((settle.unapplied||{})[pid]||0)}});return{players:ids.map(pid=>({id:pid,name:nameOf(pid)})),standings,settle,rounds,extras,golfOnly,total,hasExtras:extras.length>0,netsToZero:!!money2.netsToZero,finalized,complete:finalized.length>=(model.rounds||[]).length,prepaidNote,tripName:(model.trip||{}).name||"EGT CUP"}}return{build,money,tone,settleUp,workLines,cents}})();if(typeof window!=="undefined"){Object.assign(window,{EgtMoneySummary})}
